-- 1. 용어 데이터 초기화 및 적재
INSERT INTO public.glossary (id, term, category, standard_definition, easy_explanation, example, accounting_tip, related_question_id)
VALUES
(1, '매출채권', '자산', '일반적인 상거래에서 발생한 외상매출금과 받을어음을 통칭하는 계정과목입니다.', '친구나 손님에게 물건을 먼저 건네주고, "나중에 돈 줄게"라고 약속받아 장부에 적어둔 외상값 청구 권리예요.', '옷 가게에서 단골손님에게 10만 원어치 옷을 외상으로 주고 다음 달에 받기로 했을 때의 10만 원.', '자산(유동자산 중 당좌자산)에 속하며, 차변에 증가하고 돈을 받으면 대변에 사라집니다.', 108),
(2, '매입채무', '부채', '일반적인 상거래에서 재고자산을 외상으로 매입하면서 발생한 외상매입금과 지급어음을 통칭합니다.', '내가 도매상에서 물건을 외상으로 떼어오고 "나중에 꼭 갚을게요"라고 빚진 외상 빚 장부예요.', '편의점 사장님이 본사로부터 삼각김밥 50만 원어치를 들여오고 대금은 30일 뒤 결제하기로 한 빚.', '부채(유동부채)에 속하며, 외상 매입 시 대변에 기록하고 돈을 갚으면 차변으로 감소합니다.', 109),
(3, '유동자산 vs 비유동자산', '자산', '보고기간종료일(결산일)로부터 1년 이내에 현금화될 것으로 예상되는 자산은 유동자산, 1년 이상 장기 보유하는 자산은 비유동자산입니다.', '지갑 속 1년 안에 쓸 수 있는 빠른 현금(유동)과 최소 1년 이상 두고두고 사업에 쓸 부동산·기계(비유동)의 차이예요.', '오늘 언제든 뽑아 쓰는 보통예금은 유동자산, 10년 동안 쓸 사무실 건물과 공장 기계는 비유동자산.', '전산회계 시험에서 "유동자산이 아닌 것은?" 단골 출제! (토지, 건물, 기계장치, 비품은 비유동자산/유형자산)', 108),
(4, '비품', '자산', '기업의 영업활동에 사용할 목적으로 보유하며, 내용연수(사용기간)가 1년 이상인 사무용 집기류나 가전제품을 뜻합니다.', '사무실에서 일하려고 사둔 컴퓨터, 복사기, 에어컨, 책상 같은 오래 쓰는 살림살이예요.', '직원들 시원하게 일하라고 사무실 벽에 설치한 300만 원짜리 스탠드 에어컨.', '상품(판매 목적)과 헷갈리지 마세요! 판매용 가구는 [상품], 우리 회사 사무실용 책상은 [비품]입니다.', 113),
(5, '재고자산', '자산', '정상적인 영업 과정에서 판매를 목적으로 보유하거나 생산 과정에 있는 자산 및 원재료입니다.', '가게 선반에 손님한테 팔려고 가지런히 진열해 둔 모든 상품과 공장에서 만들고 있는 완성품들이에요.', '스마트폰 대리점 매장에 진열된 최신 갤럭시/아이폰 미개봉 새 박스들.', '선입선출법(먼저 산 것 먼저 판매)과 후입선출법(나중에 산 것 먼저 판매) 단가 산정 문제가 자주 출제됩니다.', 106),
(6, '대손상각비 & 대손충당금', '비용', '외상매출금이나 어음 등 채권의 회수가 불가능해졌을 때 비용으로 처리하는 계정(대손상각비)과 미리 떼일 것을 대비해 모아두는 저금통(대손충당금)입니다.', '외상값을 떼일까 봐 미리 준비해 둔 "비상 우산"(충당금)과 진짜로 떼여서 마음 아프게 날린 "손해 비용"(상각비).', '친구에게 빌려준 10만 원 중 2만 원은 못 받을 것 같아 미리 떼어두고, 친구가 야반도주했을 때 털어내는 것.', '기말 대손충당금 = 목표잔액 - 기존 잔액 (보충법 계산 시험 필수 공식!)', 104),
(7, '현금과부족', '기본원리', '실제 보유한 현금과 장부상 현금 잔액이 일치하지 않을 때, 일시적으로 그 차이를 맞춰두기 위해 사용하는 임시계정입니다.', '장부엔 10만 원이 있다는데 금고를 세어보니 8만 원밖에 없을 때! "원인 찾을 때까지 일단 임시 딱지 붙여두자" 하는 메모지예요.', '오늘 저녁 마감 정산할 때 영수증 1장이 없어져서 금고 돈이 2만 원 빌 때 적어두는 임시 장부.', '결산일까지 끝내 원인을 못 찾으면 [잡손실] 또는 [잡이익]으로 털고 반드시 장부에서 없애야 합니다!', 114),
(8, '선급비용 (선급보험료/임차료)', '자산', '아직 기간이 경과하지 않았으나 당기에 미리 지급한 비용 중 차기(내년)에 속하는 부분을 자산으로 이연 처리하는 계정입니다.', '1년 치 넷플릭스나 헬스장 요금을 미리 일시불로 결제했을 때, 아직 쓰지 않고 남아있는 미래의 이용권 가치예요.', '10월 1일에 1년 치 화재보험료 120만 원을 냈다면, 내년 9개월 치 90만 원은 내년 몫이므로 미리 낸 자산(선급비용)!', '결산 때 선급비용으로 정리하지 않으면 당기 비용이 너무 많이 잡혀(비용 과대계상) 이익이 왜곡됩니다.', 115),
(9, '취득원가 (부대비용 포함 원칙)', '기본원리', '자산을 구입할 때 지출한 매입가격뿐만 아니라 자산을 본래 목적에 사용할 수 있는 상태로 만드는 데 들어간 운반비, 설치비, 시운전비 등 부대비용을 모두 포함한 금액입니다.', '세탁기를 50만 원에 사고 배송비 3만 원, 사다리차 7만 원을 줬다면 내 세탁기의 진짜 몸값은 총 60만 원으로 장부에 적는 규칙!', '기계 600만 원 + 운반비 50만 원 + 설치비 30만 원 = 기계장치 취득원가 680만 원!', '구입 시 지출된 운반비는 절대 [운반비] 비용으로 쓰지 않고 [기계장치]나 [상품] 원가에 합산합니다.', 107),
(10, '거래의 8요소 & 분개', '기본원리', '차변(왼쪽: 자산증가, 부채감소, 자본감소, 비용발생)과 대변(오른쪽: 자산감소, 부채증가, 자본증가, 수익발생)의 결합 원리입니다.', '회계 장부의 양팔 저울! 왼쪽(차변)에 무언가 들어오면 오른쪽(대변)에 반드시 그 원인이나 대가가 똑같은 무게로 맞물려요.', '현금 10만 원을 은행에서 대출받으면: (차변) 현금 10만 원 늘어남 / (대변) 단기차입금(빚) 10만 원 늘어남.', '차변=자산↑, 비용↑ / 대변=부채↑, 자본↑, 수익↑ 이것만 외워도 회계 1급까지 평생 써먹습니다!', 112)
ON CONFLICT (id) DO UPDATE SET
    term = EXCLUDED.term,
    category = EXCLUDED.category,
    standard_definition = EXCLUDED.standard_definition,
    easy_explanation = EXCLUDED.easy_explanation,
    example = EXCLUDED.example,
    accounting_tip = EXCLUDED.accounting_tip,
    related_question_id = EXCLUDED.related_question_id;

-- 시퀀스 동기화
SELECT setval('glossary_id_seq', (SELECT MAX(id) FROM public.glossary));


-- 2. 기출문제 데이터 적재 (제124회 전산회계 2급 샘플)
INSERT INTO public.questions (id, exam_session, exam_session_id, category, question_text, options, correct_answer, easy_solution, exam_tip, related_glossary_term, t_accounts)
VALUES
(101, '제124회 전산회계 2급', '124-2', '분개 원리 및 거래', '기업의 거래는 기간 손익에 영향을 미치지 않는 교환거래와, 기간 손익에 영향을 미치는 손익거래로 나눌 수 있다. 다음 중 교환거래에 해당하지 않는 것은?',
 '["상품 구입대금은 90일 만기 어음으로 지급", "거래대금의 10%는 계약금으로 먼저 수령", "선지급한 임차료를 기간 경과분에 따라 인식", "받을어음이 만기가 도래하여 보통예금으로 입금"]'::jsonb,
 2, '💡 손익거래란 당기의 수익이나 비용이 발생해서 회사의 순이익(손익)을 변하게 만드는 거래예요! 3번은 날짜가 지나면서 임차료라는 [비용]이 실제로 발생하므로 손익거래입니다.', '수익이나 비용 계정과목이 분개에 등장하면 무조건 손익에 영향을 줍니다!', '거래의 8요소 & 분개', NULL),

(102, '제124회 전산회계 2급', '124-2', '재무제표 기본', '다음 중 일반기업회계기준상 재무제표에 해당하지 않는 것은?',
 '["합계잔액시산표", "재무상태표", "자본변동표", "손익계산서"]'::jsonb,
 0, '💡 합계잔액시산표는 결산 전 차변/대변 금액이 맞는지 중간 검산해보는 "내부용 점검표"일 뿐 공식 재무제표가 아니에요! 공식 재무제표 5총사는 재무상태표, 손익계산서, 현금흐름표, 자본변동표, 주석입니다.', '시험 단골 오답: 합계잔액시산표와 제조원가명세서는 재무제표가 아닙니다!', '재무제표 5종 세트', NULL),

(106, '제124회 전산회계 2급', '124-2', '계정과목 분류', '다음 중 ( 가 )에 들어갈 내용으로 옳은 것은?\n"( 가 )은(는) 정상적인 영업과정에서 판매를 목적으로 보유하거나 생산과정에 있는 자산 및 생산 또는 서비스 제공과정에 투입될 자산을 말한다."',
 '["유형자산", "재고자산", "무형자산", "유가증권"]'::jsonb,
 1, '💡 핵심 키워드는 "판매를 목적으로 보유"! 영업활동에서 손님에게 팔려고 가지고 있는 모든 물건은 [재고자산]입니다.', '판매 목적 -> 재고자산 / 영업 사용 목적 -> 유형자산', '재고자산', NULL),

(108, '제124회 전산회계 2급', '124-2', '계정과목 분류', '다음 중 유동자산 항목으로만 구성된 것은?',
 '["매출채권, 건물, 토지, 구축물", "상품, 선급금, 현금, 보통예금", "현금, 받을어음, 임차보증금, 구축물", "매출채권, 미수이자, 건물, 기계장치"]'::jsonb,
 1, '💡 유동자산은 1년 안에 현금화되거나 소비되는 자산이에요! 상품, 선급금, 현금, 보통예금은 모두 1년 이내 유동자산입니다.', '부동산(토지, 건물)이 보기에 섞여 있다면 유동자산 목록에서 즉시 제외!', '유동자산 vs 비유동자산', NULL),

(109, '제124회 전산회계 2급', '124-2', '자산·부채 측정', '아래의 자료만을 이용하여 외상매입금의 당기 지급액을 계산하면 얼마인가?\n(1) 외상매입금 기초 잔액: 2,000,000원 / 기말 잔액: 1,000,000원\n(2) 기중 거래:\n• 4/2 상품 2,000,000원을 외상으로 구입하였다.\n• 5/6 상품 3,500,000원을 구입하고 대금은 당사 발행 약속어음으로 지급하였다.',
 '["3,000,000원", "4,000,000원", "4,500,000원", "6,500,000원"]'::jsonb,
 0, '💡 1) 원래 갚아야 할 외상 빚: 2,000,000원\n2) 새로 외상으로 산 빚(4/2): +2,000,000원 (5/6 거래는 어음 지급이므로 제외!)\n-> 총 외상 빚: 4,000,000원\n3) 기말 잔액이 1,000,000원이 남았으므로 갚은 돈은 3,000,000원입니다.', '약속어음 발행은 [지급어음] 계정이므로 외상매입금에 합산하지 않습니다.', '매입채무',
 '[{"title": "외상매입금 (부채 계정)", "debitTitle": "차변 (빚 갚음)", "creditTitle": "대변 (외상빚 발생)", "debits": [{"label": "당기 지급액(?)", "amount": "3,000,000"}, {"label": "기말 잔액", "amount": "1,000,000"}], "credits": [{"label": "기초 잔액", "amount": "2,000,000"}, {"label": "4/2 외상매입", "amount": "2,000,000"}], "footerLeft": {"label": "차변 합계", "amount": "4,000,000"}, "footerRight": {"label": "대변 합계", "amount": "4,000,000"}}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET
    exam_session = EXCLUDED.exam_session,
    category = EXCLUDED.category,
    question_text = EXCLUDED.question_text,
    options = EXCLUDED.options,
    correct_answer = EXCLUDED.correct_answer,
    easy_solution = EXCLUDED.easy_solution,
    exam_tip = EXCLUDED.exam_tip,
    t_accounts = EXCLUDED.t_accounts;
